use core::sync::atomic::{AtomicU32 as A,Ordering as O};fn main(){let a=A::new(4294967295);check(a.fetch_add(1,O::Relaxed)==4294967295);check(a.load(O::Acquire)==0);check(a.fetch_add(4294967295,O::Release)==0);check(a.load(O::Acquire)==4294967295);check(a.fetch_add(2147483648,O::AcqRel)==4294967295);check(a.load(O::Acquire)==2147483647);check(a.swap(0,O::SeqCst)==2147483647);check(a.load(O::Relaxed)==0);}
